    RawRow { id: "explain-apr-name", domain: "explains", reply: "APR stands for annual percentage rate: the interest plus the fees on a loan or a card, worked out over a year, so it is the number to compare two offers on rather than the headline rate. A 0% offer is only free if the balance is cleared before the rate ends, and a card's APR applies to cash withdrawals from day one.", key: &[&["apr", "annual percentage rate"],&["stand for", "stands for", "short for", "mean", "means", "meaning", "does mean", "does it mean", "does that mean", "what is a", "whats a", "what's a", "what is an", "whats an", "what's an", "what are", "what is", "whats", "what's"],], grouped: true, avoid: &["not", "isnt", "isn't", "doesnt", "doesn't", "wont", "won't", "broken", "broke", "break", "breaks", "breaking", "breakdown", "breaks down", "broke down", "fault", "faulty", "error", "leak", "leaks", "leaking", "smell", "smells", "smelly", "noisy", "stinks", "stopped", "stuck", "jammed", "repair", "fix", "cost", "costs", "price", "prices", "buy", "buying", "best", "recommend", "recommends", "recommended", "good", "any good", "cheaper", "expensive", "worth", "which", "problem", "trouble", "warranty", "guarantee", "install", "installation", "replace", "replacing", "spare", "manual", "clean", "cleaning", "descale", "bleed", "empty", "unblock", "drain", "quiet", "louder", "password", "passwords", "passcode", "ssid", "network name", "network key", "log in", "log on", "login", "sign in", "extender", "extenders", "booster", "boosters", "repeater", "repeaters", "think", "thinks", "thoughts", "opinion", "opinions", "reckon", "your take", "april", "april 1", "1 april", "month", "date of birth", "calendar"], ask: &[&["how"],&["what"],&["why"],&["explain"],&["explains"],&["explained"],&["mean"],&["means"],&["actually"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Acronym, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None }